/* CityPulse: all activity shown in the standalone workspace is synthetic. */
'use strict';
const $=(s,r=document)=>r.querySelector(s);const $$=(s,r=document)=>[...r.querySelectorAll(s)];
let data,geo,map,areas,view='overview',layerMode='activity',selected='Downtown';
const views={overview:['City overview','A closer look at how Vancouver is moving.'],neighbourhoods:['Neighbourhood explorer','Discover the patterns behind each part of the city.'],forecast:['Activity forecasts','Explore the next 24 hours, with context behind every prediction.'],anomalies:['Unusual activity','See where the city is moving outside its usual rhythm.'],history:['Historical patterns','Find past city conditions that resemble this snapshot.'],sources:['Data sources','Understand where every signal comes from.'],models:['Model performance','Measured results, reproducible experiments, and honest limitations.']};
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const scoreColor=n=>n>=83?'#ce7757':n>=65?'#d4ad55':'#65a88b';
const spark=(color='#50957a')=>`<svg class="spark" viewBox="0 0 75 32"><path d="M1 27L8 23 14 25 20 16 26 20 32 13 37 18 45 8 51 12 56 3 63 7 69 2 74 5" fill="none" stroke="${color}" stroke-width="1.7"/></svg>`;
function notify(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function chart(values,baseline=[],wide=false,labels=['00:00','06:00','12:00','18:00','23:00']){const w=wide?900:430,h=wide?270:175,p=29;const pt=a=>a.map((n,i)=>`${p+i*(w-p-12)/(a.length-1)},${h-22-n*(h-38)/100}`).join(' ');return `<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Hourly activity scores from 0 to 100"><defs><linearGradient id="fill-${wide}" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#b7d8bf" stop-opacity=".45"/><stop offset="1" stop-color="#edf5ee" stop-opacity=".1"/></linearGradient></defs>${[0,25,50,75,100].map(n=>`<line class="grid" x1="${p}" x2="${w}" y1="${h-22-n*(h-38)/100}" y2="${h-22-n*(h-38)/100}"/><text x="1" y="${h-19-n*(h-38)/100}">${n}</text>`).join('')}<polygon points="${p},${h-22} ${pt(values)} ${w-12},${h-22}" fill="url(#fill-${wide})"/>${baseline.length?`<polyline class="baseline" points="${pt(baseline)}"/>`:''}<polyline class="line" points="${pt(values)}"/>${labels.map((t,i)=>`<text x="${p+i*(w-p-20)/4}" y="${h-3}" text-anchor="${i===4?'end':'start'}">${t}</text>`).join('')}</svg>`}
function kpis(){const a=data.neighbourhoods,avg=Math.round(a.reduce((s,n)=>s+n.activity,0)/a.length),an=a.filter(n=>n.anomaly_score>=.7).length;return `<div class="kpis"><article class="card kpi"><div class="kpi-label">City activity index <span class="kpi-icon">⌁</span></div><div class="metric">${avg}<small>/ 100</small></div><div class="delta"><b>↑ ${data.city_change}%</b> vs. typical Friday</div></article><article class="card kpi"><div class="kpi-label">Transit activity <span class="kpi-icon">▣</span></div><div class="metric">${data.transit_index}<small>/ 100</small></div><div class="delta"><b>Scheduled-service proxy</b></div></article><article class="card kpi"><div class="kpi-label">Active anomalies <span class="kpi-icon">△</span></div><div class="metric">${an}<small>neighbourhoods</small></div><div class="delta"><b class="orange">${a.filter(n=>n.anomaly_score>=.9).length} high priority</b> worth a closer look</div></article><article class="card kpi"><div class="kpi-label">Weather conditions <span class="kpi-icon">☀</span></div><div class="metric">${data.weather.temperature}<small>°C · ${esc(data.weather.label)}</small></div><div class="delta">${data.weather.precipitation} mm rain <span style="margin:0 6px">·</span> ${data.weather.wind} km/h wind</div></article></div>`}
function anomalies(limit=3){return [...data.neighbourhoods].filter(n=>n.anomaly_score>=.7).sort((a,b)=>b.anomaly_score-a.anomaly_score).slice(0,limit)}
function anomalyRows(){return anomalies().map(n=>`<button class="anomaly-row" data-detail="${esc(n.name)}"><div class="anomaly-top">${esc(n.name)}<span class="change">${n.change>0?'+':''}${n.change}% ↗</span></div><p>${esc(n.summary)}</p><div class="mini-tags">${n.tags.map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div></button>`).join('')}
function overview(){const avg=Math.round(data.neighbourhoods.reduce((v,n)=>v+n.activity,0)/data.neighbourhoods.length);return `<div class="status-region"><div class="status-heading"><strong>Metro Vancouver</strong><span>Fri Sep 11 · 18:00 PDT</span><span class="dataset-badge">DEMO DATA</span></div><div class="status-metrics"><span>Activity <b>${avg}</b> <em>+${data.city_change}%</em></span><span>Transit <b>${data.transit_index}</b></span><span><b>${anomalies(30).length}</b> active anomalies</span><span><b>${data.weather.temperature}°C</b> ${esc(data.weather.label)}</span><span class="status-freshness">Snapshot · Sep 11, 2026</span></div></div><div class="operations-grid"><article class="card map-card"><div class="card-head"><h2>Neighbourhood activity</h2><select id="map-layer" class="select" aria-label="Map data layer"><option value="activity">Activity index</option><option value="anomaly">Unusual activity</option><option value="transit">Transit activity</option></select></div><div class="map-wrap"><div id="map" class="map" aria-label="Interactive Vancouver neighbourhood map"></div><div class="map-key"><span><i></i>Normal</span><span><i class="busy"></i>Elevated</span><span><i class="high"></i>Unusual</span></div></div><div class="map-bottom"><span>Select a neighbourhood to inspect</span><a href="#neighbourhoods">All neighbourhoods →</a></div></article><aside class="card exception-panel"><div class="card-head"><h2>Current activity</h2></div><dl class="summary-rows"><div><dt>Actual</dt><dd>${avg}</dd></div><div><dt>Typical</dt><dd>${Math.round(avg/(1+data.city_change/100))}</dd></div><div><dt>Change</dt><dd>+${data.city_change}%</dd></div></dl><div class="section-label">LARGEST DEVIATIONS</div><div class="anomaly-list">${anomalies().map(n=>`<button class="anomaly-row" data-detail="${esc(n.name)}"><div class="anomaly-top">${esc(n.name)}<span class="change">+${n.change}%</span></div><p>Activity ${n.activity} · Unusually high</p></button>`).join('')}</div><a class="card-link" href="#anomalies">All active anomalies →</a></aside></div><section id="analysis-area" class="analysis-area"><div class="card"><div class="card-head"><div><h2>Activity · last 24 hours</h2><p>Citywide</p></div></div><div class="chart wide-chart">${chart(data.hourly,data.rhythm_baseline||data.baseline,true,['19:00','01:00','07:00','13:00','18:00'])}</div><div class="legend"><span><i></i>Actual</span><span><i class="dashed"></i>Typical hourly pattern</span></div></div><div class="card"><div class="card-head"><h2>Tomorrow's forecast</h2></div><dl class="summary-rows">${[18,19,20,21,22].map(h=>`<div><dt>${h}:00</dt><dd>${data.forecast[h]}</dd></div>`).join('')}</dl><a class="card-link" href="#forecast">Hourly forecast →</a></div></section>`}
function table(rows){return `<div class="table-wrap"><table><thead><tr><th>Neighbourhood</th><th>Activity index</th><th>vs. baseline</th><th>Anomaly score</th><th>Current state</th><th></th></tr></thead><tbody>${rows.map(n=>`<tr data-id="${esc(n.name)}" tabindex="0" aria-label="Explore ${esc(n.name)}"><td><b>${esc(n.name)}</b></td><td>${n.activity}<span class="score-bar"><i style="width:${n.activity}%;background:${scoreColor(n.activity)}"></i></span></td><td style="color:${n.change>25?'#c98949':'#658b60'}">${n.change>0?'+':''}${n.change}%</td><td>${n.anomaly_score.toFixed(2)}</td><td><span class="tag">${n.anomaly_score>=.7?'Unusual':n.activity>=65?'Busy':'Normal'}</span></td><td>↗</td></tr>`).join('')}</tbody></table></div>`}
function neighbourhoods(){return `<article class="card full-panel"><div class="toolbar"><input class="input" id="search" type="search" placeholder="Search neighbourhoods…" aria-label="Search neighbourhoods"><select id="sort" class="select" aria-label="Sort neighbourhoods"><option value="activity">Highest activity</option><option value="name">Name A–Z</option><option value="anomaly_score">Highest anomaly</option></select></div><div id="neighbourhood-table">${table([...data.neighbourhoods].sort((a,b)=>b.activity-a.activity))}</div></article>`}
function forecast(){return `<article class="card full-panel"><div class="toolbar"><div><h2>24-hour activity forecast</h2><p class="muted">Saturday, September 12 · 00:00–23:00 PDT</p></div><select class="select" id="forecast-area" aria-label="Forecast neighbourhood"><option value="city">Citywide average</option>${data.neighbourhoods.map(n=>`<option>${esc(n.name)}</option>`).join('')}</select></div><div id="forecast-body">${forecastBody()}</div></article>`}
function forecastBody(name='city'){const n=data.neighbourhoods.find(n=>n.name===name);const f=n?n.forecast:data.forecast;const p=Math.max(...f),hour=f.indexOf(p);return `<div class="chart wide-chart">${chart(f,data.baseline,true)}</div><div class="legend"><span><i></i>Predicted activity</span><span><i class="dashed"></i>Historical reference</span></div><div class="detail-metrics"><div>Peak activity<b>${p} / 100</b></div><div>Peak hour<b>${hour}:00</b></div><div>One-step error (MAE)<b>${data.metrics?.mae??'—'}</b></div></div><p class="muted">Synthetic-data model. Typical absolute error: ${data.metrics?.mae??'not evaluated'} points on a time-based holdout. This measures one-step predictions, not the full 24-hour forecast or a calibrated confidence interval.</p><div class="explanation">${n?esc(n.explanation):'Evening activity is strongest in this sample. The model uses the previous activity level, hour, day of week, event intensity, weather and scheduled transit. These associations are not proof of causation.'}</div>`}
function anomalyPage(){return `${kpis()}<article class="card full-panel"><div class="toolbar"><div><h2>Activity that deserves a closer look</h2><p class="muted">Isolation Forest scores ≥ 0.70 · Sample snapshot</p></div><select id="severity" class="select" aria-label="Filter anomaly severity"><option value=".7">All anomalies</option><option value=".9">High priority only</option></select></div><div id="anomaly-table">${table(anomalies(30))}</div></article>`}
function history(){return `<article class="card full-panel"><h2>Similar city moments</h2><p>Nearest historical hours based on normalized activity, transit, weather and event features. Similarity is descriptive, not a forecast.</p><div class="timeline-list">${data.similar.map(s=>`<article class="card history-row"><div><h3>${esc(s.label)}</h3><p>${esc(s.description)}</p></div><div class="similarity">${s.similarity}%<small>cosine similarity</small></div></article>`).join('')}</div><div class="explanation">Current pattern: <b>${esc(data.state)}</b>. ${esc(data.state_description)} All historical observations in this workspace are synthetic.</div></article>`}
function sources(){return `<div class="cards-grid">${[{icon:'▧',title:'Vancouver neighbourhoods',status:'Official geography',text:'22 local area boundaries downloaded from the City of Vancouver. Geometry is real; activity overlaid on it is synthetic.',url:'https://opendata.vancouver.ca/explore/dataset/local-area-boundary/',link:'View municipal dataset'},{icon:'▣',title:'Transit schedules',status:'Synthetic demo',text:'The pipeline includes a GTFS schedule adapter. Scheduled departures are a service-supply proxy, not passenger counts or real-time vehicle observations.',url:'https://www.translink.ca/about-us/doing-business-with-translink/app-developer-resources',link:'TransLink developer resources'},{icon:'☀',title:'Weather',status:'Synthetic demo',text:'The Open-Meteo adapter can retrieve hourly historical weather. The published demo uses reproducible sample weather, not current conditions.',url:'https://open-meteo.com/en/docs/historical-weather-api',link:'Open-Meteo documentation'},{icon:'◷',title:'City events',status:'Synthetic demo',text:'Hourly, neighbourhood-level event intensity. Import a normalized CSV of public events to run a supplied-data pipeline.',url:null},{icon:'⌘',title:'Activity index',status:'Derived sample',text:'A 0–100 synthetic activity target used to demonstrate modelling. A real deployment must define and validate an observed activity measure.',url:null},{icon:'⊞',title:'Reproducible pipeline',status:'Local backend',text:'Python → Parquet → DuckDB/dbt → forecasting and anomalies → FastAPI. The hosted workspace reads the exported snapshot.',url:null}].map(s=>`<article class="card source"><span class="source-icon">${s.icon}</span><span class="status" style="float:right">${s.status}</span><h3>${s.title}</h3><p>${s.text}</p>${s.url?`<a href="${s.url}" target="_blank" rel="noreferrer">${s.link} ↗</a>`:''}</article>`).join('')}</div>`}
function models(){const m=data.metrics;return `<article class="card full-panel"><h2>Evaluation you can inspect</h2><p>The forecasting model is trained on synthetic observations and evaluated on later, unseen hours. These results demonstrate the workflow; they do not establish real-world predictive accuracy. The historical baseline currently has lower error than this prototype model.</p>${m?`<div class="detail-metrics"><div>Mean absolute error<b>${m.mae}</b></div><div>Root mean square error<b>${m.rmse}</b></div><div>Baseline MAE<b>${m.baseline_mae}</b></div></div><div class="table-wrap"><table><tbody><tr><td>Forecast model</td><td>${esc(m.model)}</td></tr><tr><td>Training observations</td><td>${m.train_rows.toLocaleString()}</td></tr><tr><td>Holdout observations</td><td>${m.test_rows.toLocaleString()}</td></tr><tr><td>Split</td><td>Last 7 days held out by timestamp</td></tr><tr><td>Anomaly detection</td><td>Isolation Forest · training-only fit</td></tr><tr><td>Historical retrieval</td><td>Standardized numerical vectors · cosine similarity</td></tr><tr><td>Clustering</td><td>K-Means · 5 city states</td></tr></tbody></table></div>`:'<div class="explanation">Model evaluation is being prepared. No unmeasured performance claims are shown.</div>'}<p class="muted" style="margin-top:22px">Feature contributions explain model associations. Explanations use deterministic templates grounded in those values; no LLM is connected.</p></article>`}
function detail(name){const n=data.neighbourhoods.find(n=>n.name===name);if(!n)return;selected=name;$('#detail-content').innerHTML=`<div class="eyebrow">NEIGHBOURHOOD INTELLIGENCE</div><h2>${esc(n.name)}</h2><p class="muted">Friday, September 11 · 18:00 PDT · Sample snapshot</p><div class="detail-metrics"><div>Activity<b>${n.activity}<small style="font-size:13px"> / 100</small></b></div><div>vs. usual<b>${n.change>0?'+':''}${n.change}%</b></div><div>Anomaly<b>${n.anomaly_score.toFixed(2)}</b></div></div><div class="explanation">${esc(n.explanation)}</div><h3>What influences the activity estimate?</h3><div class="drivers">${n.drivers.map(d=>`<div class="driver"><span>${esc(d.label)}</span><div class="driver-track"><i class="${d.value<0?'negative':''}" style="width:${Math.min(100,Math.abs(d.value)*4)}%"></i></div><b>${d.value>0?'+':''}${d.value}</b></div>`).join('')}</div><p class="muted">${esc(data.explanation_method||'Illustrative feature contributions')}. Associations do not establish causation.</p><h3>Tomorrow's activity</h3><div class="chart">${chart(n.forecast)}</div><button class="button primary" id="detail-forecast">Explore full forecast →</button>`;$('#detail-forecast').onclick=()=>{$('#detail').close();location.hash='forecast';setTimeout(()=>{if($('#forecast-area')){$('#forecast-area').value=name;$('#forecast-body').innerHTML=forecastBody(name)}},30)};$('#detail').showModal()}
function initMap(){if(!window.L||!geo){$('#map').innerHTML='<p class="full-panel">Map unavailable. Explore neighbourhoods using the table.</p>';return}map=L.map('map',{zoomControl:false,scrollWheelZoom:false}).setView([49.265,-123.106],12);L.control.zoom({position:'topright'}).addTo(map);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>',maxZoom:18}).addTo(map);areas=L.geoJSON(geo,{style:feature=>areaStyle(feature),onEachFeature:(f,l)=>{const name=f.properties.name;l.bindTooltip(name,{sticky:true});l.on('click',()=>detail(name));l.on('mouseover',()=>l.setStyle({weight:2,fillOpacity:.6}));l.on('mouseout',()=>areas.resetStyle(l))}}).addTo(map);map.fitBounds(areas.getBounds(),{padding:[15,10]});[['Downtown',49.282,-123.117],['Kitsilano',49.269,-123.163],['Mount Pleasant',49.260,-123.099],['Hastings-Sunrise',49.277,-123.042],['Riley Park',49.246,-123.103]].forEach(([name,lat,lng])=>L.marker([lat,lng],{icon:L.divIcon({className:'map-label',html:name,iconSize:[100,16]}),interactive:false,keyboard:false}).addTo(map));$('#map-layer').value=layerMode;$('#map-layer').onchange=e=>{layerMode=e.target.value;areas.setStyle(f=>areaStyle(f));notify(`Map shows ${layerMode==='anomaly'?'anomaly scores':layerMode==='transit'?'transit activity':'activity index'}`)}}
function areaStyle(f){const n=data.neighbourhoods.find(n=>n.name===f.properties.name);const value=n?(layerMode==='anomaly'?n.anomaly_score*100:layerMode==='transit'?n.transit:n.activity):30;return {color:'#fff',weight:1.4,fillColor:scoreColor(value),fillOpacity:.38}}
function render(){view=location.hash.slice(1);if(!views[view])view='overview';if(map){map.remove();map=null}$('#page-title').textContent=views[view][0];$('#page-subtitle').textContent=views[view][1];$('#crumb').textContent=$(`[data-view="${view}"]`).textContent.trim().replace(/^[^A-Za-z]+/,'').replace(/\d+$/,'');$$('[data-view]').forEach(a=>a.classList.toggle('active',a.dataset.view===view));$('#content').innerHTML=({overview,neighbourhoods,forecast,anomalies:anomalyPage,history,sources,models})[view]();if(view==='overview')initMap();if(view==='neighbourhoods'){const filter=()=>{let rows=data.neighbourhoods.filter(n=>n.name.toLowerCase().includes($('#search').value.toLowerCase()));const key=$('#sort').value;rows.sort((a,b)=>key==='name'?a.name.localeCompare(b.name):b[key]-a[key]);$('#neighbourhood-table').innerHTML=rows.length?table(rows):'<p class="muted">No neighbourhoods match your search.</p>'};$('#search').oninput=filter;$('#sort').onchange=filter}if(view==='forecast')$('#forecast-area').onchange=e=>$('#forecast-body').innerHTML=forecastBody(e.target.value);if(view==='anomalies')$('#severity').onchange=e=>$('#anomaly-table').innerHTML=table(anomalies(30).filter(n=>n.anomaly_score>=Number(e.target.value)))}
$('#content').addEventListener('click',e=>{const target=e.target.closest('[data-detail],[data-id]');if(target)detail(target.dataset.detail||target.dataset.id)});$('#content').addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-id]')){e.preventDefault();detail(e.target.dataset.id)}});$('.close').onclick=()=>$('#detail').close();$('#detail').addEventListener('click',e=>{if(e.target===$('#detail')){const r=$('#detail').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#detail').close()}});$('#about').onclick=()=>{$('#detail-content').innerHTML='<div class="eyebrow">ABOUT THIS WORKSPACE</div><h2>Meet CityPulse.</h2><div class="explanation">A reproducible urban analytics portfolio for Vancouver. Activity, transit, weather and events in this demo are synthetic. Neighbourhood boundaries are official city geography.</div><p class="muted">Explore neighbourhoods, inspect anomaly scores, compare forecast patterns, and review model evaluation. The included Python backend can regenerate this snapshot and serve it through FastAPI. Live production feeds, real-world model validation, and an LLM connection are not enabled.</p>';$('#detail').showModal()};$('#export').onclick=()=>{if(!data)return;const a=document.createElement('a');const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.href=url;a.download='citypulse-snapshot-2026-09-11.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Snapshot exported with provenance and model metrics')};
async function boot(){try{const r=await fetch('snapshot.json');if(!r.ok)throw Error('Snapshot could not be loaded');data=await r.json();try{const g=await fetch('neighbourhoods.geojson');geo=await g.json()}catch{}$('#nav-count').textContent=anomalies(30).length;render();window.addEventListener('hashchange',render);if(document.modelContext?.registerTool){try{await document.modelContext.registerTool({name:'inspect_neighbourhood',description:'Open a Vancouver neighbourhood detail panel with sample activity and forecasting evidence.',inputSchema:{type:'object',properties:{name:{type:'string'}},required:['name'],additionalProperties:false},annotations:{readOnlyHint:false},execute:({name})=>{if(typeof name!=='string'||!data.neighbourhoods.some(n=>n.name===name))throw Error('Unknown neighbourhood');if($('#detail').open)$('#detail').close();detail(name);const n=data.neighbourhoods.find(n=>n.name===name);return {name:n.name,activity:n.activity,anomaly_score:n.anomaly_score,source:'synthetic'}}})}catch(e){console.warn('Optional agent interface unavailable',e)}}}catch(e){$('#content').innerHTML='<article class="card full-panel"><h2>Snapshot unavailable</h2><p>Reload the page to try again. The data file could not be loaded.</p><button class="button" onclick="location.reload()">Reload snapshot</button></article>'}}